import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 크기 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00704Controller {
  @Get('/cash-receipts')
  async listCashReceipts(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const fromDate = String(q['fromDate'] ?? '').trim();
    const toDate = String(q['toDate'] ?? '').trim();
    if (!DATE_PATTERN.test(fromDate) || !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간(시작일·종료일)을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const rawPage = q['page'];
    const rawSize = q['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    let size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 쪽 크기 형식이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const params = {
        fromDate,
        toDate,
        size,
        offset: page * size,
      };
      const totals = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM cash_receipt
          WHERE issued_at >= CAST(:fromDate AS date)
            AND issued_at < CAST(:toDate AS date) + 1`,
        { fromDate, toDate },
      );
      const items = await db.query(
        `SELECT cash_receipt_id AS "cashReceiptId",
                approval_no AS "approvalNo",
                issued_at AS "issuedAt",
                merchant_name AS "merchantName",
                total_amount AS "totalAmount",
                expense_resolution_id AS "expenseResolutionId"
           FROM cash_receipt
          WHERE issued_at >= CAST(:fromDate AS date)
            AND issued_at < CAST(:toDate AS date) + 1
          ORDER BY issued_at DESC, cash_receipt_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      return {
        items,
        page,
        size,
        total: Number(totals[0]?.total ?? 0),
      };
    });
  }
}

