import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  DateInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

interface Target {
  kind: 'cash' | 'card';
  row: Row;
}

const SIZE = 20;

export default function FnSfr00704Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [applied, setApplied] = useState({ fromDate: '', toDate: '' });
  const [cashPage, setCashPage] = useState(0);
  const [cardPage, setCardPage] = useState(0);
  const [target, setTarget] = useState<Target | null>(null);
  const [form, setForm] = useState<Row>({});

  const ready = applied.fromDate !== '' && applied.toDate !== '';

  const cash = useData<Page | null>(
    () => (ready
      ? call<Page>('GET', '/cash-receipts', role, undefined, { fromDate: applied.fromDate, toDate: applied.toDate, page: cashPage, size: SIZE })
      : Promise.resolve(null)),
    [applied, cashPage, role],
  );
  const card = useData<Page | null>(
    () => (ready
      ? call<Page>('GET', '/card-transactions', role, undefined, { startDate: applied.fromDate, endDate: applied.toDate, page: cardPage, size: SIZE })
      : Promise.resolve(null)),
    [applied, cardPage, role],
  );

  const search = () => {
    if (!fromDate || !toDate) {
      notify('조회 기간을 입력하세요.');
      return;
    }
    setCashPage(0);
    setCardPage(0);
    setApplied({ fromDate, toDate });
  };

  const reset = () => {
    setFromDate('');
    setToDate('');
    setApplied({ fromDate: '', toDate: '' });
  };

  const open = (kind: 'cash' | 'card', row: Row) => {
    setTarget({ kind, row });
    setForm({
      resolutionDate: '',
      amount: row['totalAmount'],
      evidenceType: kind === 'cash' ? '현금영수증' : '카드',
    });
  };

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const submit = async () => {
    if (!form['resolutionDate'] || !form['projectId'] || !form['budgetItemId'] || !form['departmentId'] || form['amount'] === '' || form['amount'] === undefined) {
      throw new Error('결의일자, 프로젝트, 예산과목, 결의 금액, 결의부서는 필수입니다.');
    }
    await call('POST', '/expense-resolutions', role, {
      resolutionDate: form['resolutionDate'],
      purchaseRequestId: form['purchaseRequestId'] || undefined,
      projectId: form['projectId'],
      budgetItemId: form['budgetItemId'],
      amount: form['amount'],
      evidenceType: form['evidenceType'],
      partnerId: form['partnerId'] || undefined,
      departmentId: form['departmentId'],
    });
    notify('결의서를 작성했습니다.');
    setTarget(null);
    cash.reload();
    card.reload();
  };

  const doneBadge = (row: Row) => (row['expenseResolutionId'] ? <Badge value="작성 완료" /> : <Badge value="대기" />);

  const actionCell = (kind: 'cash' | 'card') => (row: Row) => (
    row['expenseResolutionId']
      ? null
      : <button type="button" onClick={(e) => { e.stopPropagation(); open(kind, row); }}>결의서 작성</button>
  );

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 기간</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
        </Filters>
      </section>

      <section className="box span-12">
        <h2>현금영수증 내역</h2>
        <Band total={cash.data?.total} />
        {cash.error ? <ErrorText text={cash.error} /> : null}
        <DataTable
          rows={cash.data?.items ?? []}
          empty={ready ? '조회된 내역이 없습니다.' : '조회 기간을 입력하세요.'}
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            { key: 'issuedAt', label: '발행일시', render: (r) => <DateText value={r['issuedAt']} time /> },
            { key: 'merchantName', label: '가맹점명' },
            { key: 'totalAmount', label: '합계금액', render: (r) => <Num value={r['totalAmount']} /> },
            { key: 'expenseResolutionId', label: '결의서', render: (r) => (r['expenseResolutionId'] ? <RefName table="expense_resolution" role={role} value={r['expenseResolutionId']} /> : doneBadge(r)) },
            { key: 'action', label: '처리', render: actionCell('cash') },
          ]}
        />
        <Pager page={cash.data?.page ?? 0} size={SIZE} total={cash.data?.total ?? 0} onPage={setCashPage} />
      </section>

      <section className="box span-12">
        <h2>카드 승인내역</h2>
        <Band total={card.data?.total} />
        {card.error ? <ErrorText text={card.error} /> : null}
        <DataTable
          rows={card.data?.items ?? []}
          empty={ready ? '조회된 내역이 없습니다.' : '조회 기간을 입력하세요.'}
          columns={[
            { key: 'creditCardId', label: '신용카드', render: (r) => <RefName table="credit_card" role={role} value={r['creditCardId']} /> },
            { key: 'approvalNo', label: '승인번호' },
            { key: 'approvedAt', label: '승인일시', render: (r) => <DateText value={r['approvedAt']} time /> },
            { key: 'merchantName', label: '가맹점명' },
            { key: 'totalAmount', label: '합계금액', render: (r) => <Num value={r['totalAmount']} /> },
            { key: 'evidenceType', label: '증빙 유형', render: (r) => <Badge value={r['evidenceType']} /> },
            { key: 'action', label: '처리', render: actionCell('card') },
          ]}
        />
        <Pager page={card.data?.page ?? 0} size={SIZE} total={card.data?.total ?? 0} onPage={setCardPage} />
      </section>

      {target ? (
        <Drawer title="결의서 작성" onClose={() => setTarget(null)}>
          <Form onSubmit={submit} submit="결의서 작성">
            <Field label="결의일자" required>
              <DateInput value={form['resolutionDate']} onChange={(v) => set('resolutionDate', v)} />
            </Field>
            <Field label="연결 품의서">
              <LookupSelect table="purchase_request" role={role} value={form['purchaseRequestId']} onChange={(v) => set('purchaseRequestId', v)} />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={form['projectId']} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={form['budgetItemId']} onChange={(v) => set('budgetItemId', v)} />
            </Field>
            <Field label="결의 금액" required>
              <NumberInput value={form['amount']} onChange={(v) => set('amount', v)} />
            </Field>
            <Field label="증빙 유형">
              <Badge value={form['evidenceType']} />
            </Field>
            <Field label="거래처">
              <LookupSelect table="partner" role={role} value={form['partnerId']} onChange={(v) => set('partnerId', v)} />
            </Field>
            <Field label="결의부서" required>
              <LookupSelect table="department" role={role} value={form['departmentId']} onChange={(v) => set('departmentId', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
